import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: e나라도움 연계 규격이 제공되지 않아 실제 VPN 송수신 호출 없이 연계 이력만 기록하고 결과는 SUCCESS로 한다.
const TARGET_SYSTEM = 'e나라도움';
const ROLE = '예산·회계 담당자';

type Db = { query: (sql: string, params: object) => Promise<any[]> };

function requiredText(value: unknown, label: string, max?: number): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) 입력하세요.');
  }
  if (max !== undefined && value.length > max) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '은(는) ' + max + '자 이내로 입력하세요.');
  }
  return value;
}

async function insertLog(
  db: Db,
  direction: string,
  interfaceName: string,
  requestSummary: string | null,
  responseSummary: string | null,
): Promise<any> {
  const rows = await db.query(
    `INSERT INTO integration_log (
      target_system, direction, interface_name, result_status, failure_reason,
      occurred_at, request_summary, response_summary, created_at, updated_at
    ) VALUES (
      :targetSystem, :direction, :interfaceName, 'SUCCESS', NULL,
      now(), :requestSummary, :responseSummary, now(), now()
    )
    RETURNING integration_log_id AS "integrationLogId", result_status AS "resultStatus", failure_reason AS "failureReason"`,
    {
      targetSystem: TARGET_SYSTEM,
      direction,
      interfaceName,
      requestSummary,
      responseSummary,
    },
  );
  return rows[0];
}

@Controller('api/v1')
export class FnSfr00103Controller {
  @Post('/enaradoum-integrations/send')
  @HttpCode(200)
  async sendEnaradoumData(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const interfaceName = requiredText(data['interfaceName'], '연계 구분', 100);
    const requestSummary = requiredText(data['requestSummary'], '요청 데이터 요약');
    return transaction(async (db) => {
      return insertLog(db, 'SEND', interfaceName, requestSummary, null);
    });
  }

  @Post('/enaradoum-integrations/receive')
  @HttpCode(200)
  async receiveEnaradoumData(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const interfaceName = requiredText(data['interfaceName'], '연계 구분', 100);
    const responseSummary = requiredText(data['responseSummary'], '응답 데이터 요약');
    return transaction(async (db) => {
      return insertLog(db, 'RECEIVE', interfaceName, null, responseSummary);
    });
  }
}

