import { useState } from 'react';
import { call, Badge, Band, DataTable, Drawer, Form, Field, TextInput, Tiles, ErrorText } from '../kit';
import type { PageProps, Row } from '../kit';

type Mode = 'send' | 'receive';

export default function FnSfr00103Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [mode, setMode] = useState<Mode | null>(null);
  const [interfaceName, setInterfaceName] = useState('');
  const [summary, setSummary] = useState('');

  const sendCount = results.filter((r) => r['direction'] === 'SEND').length;
  const receiveCount = results.filter((r) => r['direction'] === 'RECEIVE').length;
  const failCount = results.filter((r) => r['resultStatus'] === 'FAILURE').length;

  function open(next: Mode) {
    setInterfaceName('');
    setSummary('');
    setMode(next);
  }

  async function submit() {
    if (!mode) return;
    if (interfaceName.trim() === '') {
      throw new Error('연계 구분을 입력하세요.');
    }
    if (summary.trim() === '') {
      throw new Error(mode === 'send' ? '요청 데이터 요약을 입력하세요.' : '응답 데이터 요약을 입력하세요.');
    }
    const path = mode === 'send' ? '/enaradoum-integrations/send' : '/enaradoum-integrations/receive';
    const body: Row = mode === 'send'
      ? { interfaceName, requestSummary: summary }
      : { interfaceName, responseSummary: summary };
    const res = await call<Row>('POST', path, role, body);
    setResults((prev) => [
      { ...res, direction: mode, interfaceName },
      ...prev,
    ]);
    notify(mode === 'send' ? '송신했습니다.' : '수신했습니다.');
    setMode(null);
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>연동 현황</h2>
        <Tiles items={[
          ['송신', sendCount],
          ['수신', receiveCount],
          ['실패', failCount],
        ]} />
      </section>
      <section className="box span-12">
        <h2>연동 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={() => open('send')}>송신</button>
          <button type="button" onClick={() => open('receive')}>수신</button>
        </Band>
        <DataTable
          columns={[
            { key: 'integrationLogId', label: '외부 연계 이력 ID' },
            {
              key: 'direction',
              label: '연계 방향',
              render: (r) => (r['direction'] === 'SEND' ? '송신' : '수신'),
            },
            { key: 'interfaceName', label: '연계 구분' },
            { key: 'resultStatus', label: '연계 결과', render: (r) => <Badge value={r['resultStatus']} /> },
            {
              key: 'failureReason',
              label: '실패 사유',
              render: (r) => (r['failureReason'] ? <ErrorText text={String(r['failureReason'])} /> : <span>-</span>),
            },
          ]}
          rows={results}
          empty="처리한 연동이 없습니다."
        />
      </section>
      {mode && (
        <Drawer title={mode === 'send' ? 'e나라도움 송신' : 'e나라도움 수신'} onClose={() => setMode(null)}>
          <Form onSubmit={submit} submit={mode === 'send' ? '송신' : '수신'}>
            <Field label="연계 구분" required>
              <TextInput value={interfaceName} onChange={setInterfaceName} />
            </Field>
            <Field label={mode === 'send' ? '요청 데이터 요약' : '응답 데이터 요약'} required wide>
              <TextInput value={summary} onChange={setSummary} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
